fn fixed(n: f64) -> String {
    if n.is_nan() {
        "NaN".into()
    } else if n.is_infinite() {
        if n.is_sign_negative() {
            "-Infinity".into()
        } else {
            "Infinity".into()
        }
    } else {
        format!("{n:.2}")
    }
}
fn log(message: &str, data: Value) -> Value {
    json!({"op":"log","message":message,"data":data})
