        e.config["gacha"]["fiveStar"]["limitedRate"] = json!(0);
        e.config["gacha"]["fiveStar"]["radiance"]["limitedRate"] = json!(1);
        for expected in [1, 1, 2, 2, 3, 3] {
            e.draw();
