        e.config["gacha"]["fiveStar"]["softPityStep"] = json!(0);
        e.config["gacha"]["fourStar"]["baseRate"] = json!(0);
        for _ in 0..1000 {
            e.draw();
            assert!(num(&e.state["pity5"]) < 20.0);
            assert!(num(&e.state["pity4"]) < 10.0);
        }
    }
    #[test]
